import sys
from datetime import datetime, timezone


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string."""
    # Handle 'Z' suffix as +00:00
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


def format_utc(dt):
    """Format a datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def main():
    with open(sys.argv[1], "r") as f:
        data = json.load(f)

    as_of_dt = parse_offset_aware(data["as_of"])

    results = []
    for r in data["reminders"]:
        # Skip completed reminders
        if r.get("completed", False):
            continue

        due_raw = r.get("due")
        # Skip null or missing due values
        if due_raw is None:
            continue

        # Skip naive due values (no timezone offset)
        # A naive ISO8601 string has no +/-HH:MM or Z suffix
        if not isinstance(due_raw, str):
            continue

        # Check if the string represents an offset-aware datetime
        # Naive strings won't have 'Z', 'z', or '+'/'-' offset patterns
        # We try parsing; if it succeeds and has tzinfo, it's offset-aware
        try:
            due_dt = parse_offset_aware(due_raw)
        except (ValueError, TypeError):
            continue

        # Skip if the result is naive (no timezone info)
        if due_dt.tzinfo is None:
            continue

        # Include pending reminders due AT OR BEFORE as_of
        if due_dt <= as_of_dt:
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": format_utc(due_dt)
            })

